\begin{definition}[Singular chain norm]
\label{thurston-ch06-singular-chain-norm}
\group{gromov-invariant}
\source{thurston:page-0136}

For a real singular chain $c=\sum_i a_i\sigma_i$ on a space $X$, define
\[
\|c\|=\sum_i|a_i|.
\]
\end{definition}
